package org.happyrun.app.remote.runtime;
import org.junit.Test;import static org.junit.Assert.*;
import java.nio.file.*;import java.time.*;import java.util.*;
import org.happyrun.app.remote.protocol.*;import org.happyrun.app.remote.transport.*;import org.happyrun.app.remote.journal.*;import org.happyrun.app.remote.simulation.*;
public class RemoteAgentRunnerTest {
 static final String AGENT="33333333-3333-4333-8333-333333333333",DEVICE="44444444-4444-4444-8444-444444444444",JOB="55555555-5555-4555-8555-555555555555",SESSION="66666666-6666-4666-8666-666666666666";
 static class Clock implements RemoteClock {double now;public double monotonicSeconds(){return now;}public Instant utcNow(){return Instant.parse("2026-10-19T00:00:00Z").plusMillis((long)(now*1000));}public void sleepMillis(long ms){now+=ms/1000.;}}
 static class Client implements AgentClient {
  final Clock c;JobView view;final List<String> eventStates=new ArrayList<>();int renews,starts,acks,claims;int failRenew;boolean cancelOnRun,loseRunning,staleRunning;double renewDelay;long leaseSeconds=30;final List<Double> renewTimes=new ArrayList<>();int cancelAtRenew=3;Runnable duringRenew;
  Client(Clock c){this.c=c;JobSpec spec=new JobSpec(1,"simulation",BundledSimulationProfiles.PROFILE_ID,BundledSimulationProfiles.PROFILE_REVISION,BundledSimulationProfiles.ROUTE_ID,BundledSimulationProfiles.ROUTE_REVISION,DEVICE,c.utcNow(),c.utcNow().plusSeconds(120),null);view=new JobView(JOB,spec,"leased",1,"run",1,AGENT,null,null,null,SESSION);}
  public HelloResult hello(AgentHello h){throw new UnsupportedOperationException();}public Instant heartbeat(AgentHello h){return c.utcNow();}public void close(){}
  public LeaseGrant claim(String id){claims++;return new LeaseGrant(view,"synthetic-lease",view.fence,c.utcNow().plusSeconds(30));}
  public JobView getJob(String id){return view;}
  public RenewResult renew(String id,LeaseCommand l){renews++;renewTimes.add(c.now);if(duringRenew!=null)duringRenew.run();c.now+=renewDelay;if(renews==failRenew)throw new IllegalStateException("network_unavailable");if(cancelOnRun&&renews>=cancelAtRenew&&view.state.equals("running")){view=new JobView(JOB,view.spec,"cancelling",view.revision+1,"cancel",view.fence,AGENT,null,null,null,SESSION);return new RenewResult(c.utcNow().plusSeconds(30),"cancel");}return new RenewResult(c.utcNow().plusSeconds(leaseSeconds),"run");}
  public JobView events(String id,LeaseCommand l,JobEvent e){eventStates.add(e.state);assertEquals(view.revision,e.expectedRevision);if(staleRunning&&e.state.equals("running"))return view;view=new JobView(JOB,view.spec,e.state,view.revision+1,view.desiredState,view.fence,AGENT,e.reasonCode,e.state.equals("needs_attention")?e.resumePhase:view.resumePhase,Arrays.asList("completed","needs_attention").contains(e.state)?null:view.recoveryAction,SESSION);if(e.state.equals("running")){starts++;if(loseRunning)throw new IllegalStateException("response_lost");}return view;}
  public JobView stopAck(String id,LeaseCommand l,String event,long revision){assertEquals(view.revision,revision);acks++;return view=new JobView(JOB,view.spec,"cancelled",revision+1,"cancel",view.fence,AGENT,null,null,null,SESSION);}
 }
 @Test public void actualRouteCompletesWithDurableIntentAndStop()throws Exception {Clock c=new Clock();Client api=new Client(c);RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("completed",r.runOnce().state);assertEquals(1,d.startCount());assertEquals(1,d.stopCount());assertTrue(j.finished(JOB,SESSION));}}
 @Test public void insufficientRouteBudgetNeverCompletes()throws Exception {Clock c=new Clock();Client api=new Client(c);try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,new RemoteFakeDriver(),c,AGENT,DEVICE,.05);assertEquals("simulation_incomplete",r.runOnce().reasonCode);}}
 @Test public void lostRunningResponseNeverStarts()throws Exception {Clock c=new Clock();Client api=new Client(c);api.loseRunning=true;RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("needs_attention",r.runOnce().state);assertEquals(0,d.startCount());}}
 @Test public void renewalFailureStopsWithoutRetry()throws Exception {Clock c=new Clock();Client api=new Client(c);api.failRenew=4;RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("needs_attention",r.runOnce().state);assertEquals(4,api.renews);assertEquals(1,d.startCount());assertTrue(d.stopped());}}
 @Test public void cancellationAcknowledgedOnlyAfterStop()throws Exception {Clock c=new Clock();Client api=new Client(c);api.cancelOnRun=true;RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("cancelled",r.runOnce().state);assertTrue(d.stopped());assertEquals(1,api.acks);assertEquals(0,d.startCount());}}
 @Test public void requestedStopBeforeClaimNeverContactsServer()throws Exception {Clock c=new Clock();Client api=new Client(c);try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,new RemoteFakeDriver(),c,AGENT,DEVICE,2);r.requestStop();assertNull(r.runOnce());assertEquals(0,api.claims);}}
 @Test public void priorIntentNeverStartsAgain()throws Exception {Clock c=new Clock();Client api=new Client(c);RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){java.lang.reflect.Method digest=RemoteAgentRunner.class.getDeclaredMethod("specDigest",JobSpec.class);digest.setAccessible(true);j.bind(JOB,SESSION,1,(String)digest.invoke(null,api.view.spec));j.startIntent(JOB,SESSION,1);RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("needs_attention",r.runOnce().state);assertEquals(0,d.startCount());}}
 @Test public void lateRenewalCannotRestoreExpiredAuthority()throws Exception {Clock c=new Clock();Client api=new Client(c);api.renewDelay=30;RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2).runOnce();assertEquals(0,d.startCount());assertEquals(1,api.renews);assertTrue(d.stopped());}}
 @Test public void cancellationAfterStartUsesFreshRevision()throws Exception {Clock c=new Clock();Client api=new Client(c);api.cancelOnRun=true;api.cancelAtRenew=4;RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("cancelled",r.runOnce().state);assertEquals(1,d.startCount());assertEquals(1,d.stopCount());assertEquals(1,api.acks);}}
 @Test public void stopBetweenIntentAndEffectNeverStarts()throws Exception {Clock c=new Clock();Client api=new Client(c);RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);api.duringRenew=()->{if(api.renews==3)r.requestStop();};assertEquals("needs_attention",r.runOnce().state);assertTrue(j.hasStart(JOB));assertEquals(0,d.startCount());}}
 @Test public void verifyOnlyNeverReplaysMotion()throws Exception {Clock c=new Clock();Client api=new Client(c);api.view=new JobView(JOB,api.view.spec,"leased",4,"run",2,AGENT,null,"running","verify_only",SESSION);RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("verification_pending",r.runOnce().reasonCode);assertEquals("running",api.view.resumePhase);assertEquals(0,d.startCount());}}
 @Test public void stopOnlyNeverStartsAndAcknowledges()throws Exception {Clock c=new Clock();Client api=new Client(c);api.view=new JobView(JOB,api.view.spec,"leased",4,"cancel",2,AGENT,null,"running","stop_only",SESSION);RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("cancelled",r.runOnce().state);assertEquals("cancelled",r.localStatus());assertEquals(0,d.startCount());assertEquals(1,api.acks);}}
 @Test public void retryPreflightFailureReportsCurrentRunningPhase()throws Exception {Clock c=new Clock();Client api=new Client(c);api.view=new JobView(JOB,api.view.spec,"leased",4,"run",2,AGENT,null,"leased","retry_preflight",SESSION);api.failRenew=4;try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,new RemoteFakeDriver(),c,AGENT,DEVICE,2);assertEquals("running",r.runOnce().resumePhase);}}
 @Test public void unknownProfileIsExplicitAndNeverStarts()throws Exception {Clock c=new Clock();Client api=new Client(c);JobSpec old=api.view.spec;JobSpec changed=new JobSpec(1,"simulation",old.profileId,"0".repeat(64),old.routeId,old.routeRevision,DEVICE,old.notBefore,old.deadline,null);api.view=new JobView(JOB,changed,"leased",1,"run",1,AGENT,null,null,null,SESSION);RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("unsupported_simulation_profile",r.runOnce().reasonCode);assertEquals(0,d.startCount());}}
 @Test public void staleReadyResponseToRunningDoesNotAuthorizeStart()throws Exception {Clock c=new Clock();Client api=new Client(c);api.staleRunning=true;RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);r.runOnce();assertEquals(0,d.startCount());assertFalse(j.hasStart(JOB));}}
 @Test public void frequentTicksDoNotRenewAtTenHertz()throws Exception {Clock c=new Clock();Client api=new Client(c);try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,new RemoteFakeDriver(),c,AGENT,DEVICE,2);assertEquals("completed",r.runOnce().state);assertTrue("only bounded stage renewals, not every tick: "+api.renews,api.renews<=5);}}
 @Test public void shortLeaseDynamicallyRenewsBeforeFiveSecondInterval()throws Exception {Clock c=new Clock();Client api=new Client(c);api.leaseSeconds=6;RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);assertEquals("completed",r.runOnce().state);assertTrue(api.renewTimes.get(3)>0);assertTrue(api.renewTimes.get(3)<.8);assertEquals(1,d.startCount());}}
 @Test public void leaseBelowRequestBudgetStopsWithoutAnotherRenewal()throws Exception {Clock c=new Clock();Client api=new Client(c);api.leaseSeconds=5;RemoteFakeDriver d=new RemoteFakeDriver();try(RemoteJournal j=new RemoteJournal(Files.createTempDirectory("runner"))){RemoteAgentRunner r=new RemoteAgentRunner(api,j,d,c,AGENT,DEVICE,2);r.runOnce();assertEquals(0,d.startCount());assertEquals(1,api.renews);assertTrue(d.stopped());}}
 @Test public void stoppedFinishedRouteRecoversFromReopenedJournalWithoutMotion()throws Exception {
  Clock c=new Clock();Client api=new Client(c){boolean first=true;@Override public JobView events(String id,LeaseCommand lease,JobEvent event){if(first&&event.state.equals("completed")){first=false;throw new IllegalStateException("before_completion_report");}return super.events(id,lease,event);}};
  Path path=Files.createTempDirectory("recover-finished");RemoteFakeDriver first=new RemoteFakeDriver();
  try(RemoteJournal j=new RemoteJournal(path)){RemoteAgentRunner runner=new RemoteAgentRunner(api,j,first,c,AGENT,DEVICE,2);assertEquals("needs_attention",runner.runOnce().state);assertTrue(j.finished(JOB,SESSION));assertEquals(1,first.startCount());assertEquals(1,first.stopCount());}
  api.view=new JobView(JOB,api.view.spec,"leased",api.view.revision+1,"run",2,AGENT,null,"verifying","verify_only",SESSION);api.starts=0;api.eventStates.clear();
  RemoteFakeDriver recovered=new RemoteFakeDriver();
  try(RemoteJournal j=new RemoteJournal(path)){RemoteAgentRunner runner=new RemoteAgentRunner(api,j,recovered,c,AGENT,DEVICE,2);assertEquals("completed",runner.runOnce().state);assertEquals("completed",runner.localStatus());assertEquals(0,recovered.startCount());assertEquals(0,recovered.distanceM(),0);assertTrue(recovered.stopped());assertEquals(0,api.starts);assertEquals(Arrays.asList("verifying","completed"),api.eventStates);}
 }

}
